oxy_webhelp_navlinks = {"db2_database_restore_cdm_v9.x-d39536e34821":{"topics":[{"title":"Restoring Db2 databases for standalone environment using CLI","shortdesc":"<p class=\"shortdesc\">In CDM version 9.x, when the source and target instances are the same, restore a         database with the same instance for a standalone environment.<\/p>","href":"db2\/restoring_db2_db_standalone_cdm_v9.x.html","attributes":{"data-id":"restoring_db2_db_standalone_cdm_v9.x"},"menu":{"hasChildren":false},"tocID":"restoring_db2_db_standalone_cdm_v9.x-d39536e34832","topics":[]},{"title":"Db2 database cross restore for standalone environment","shortdesc":"<p class=\"shortdesc\">The Db2 database cross restore process to different instances in a standalone         environment involves creating and editing a template script. The modified script then         migrates data while maintaining data integrity in CDM versions 9.x.<\/p>","href":"db2\/db2_db_cross_restore_standalone_cdm_v9.x.html","attributes":{"data-id":"db2_db_cross_restore_standalone_cdm_v9.x"},"menu":{"hasChildren":false},"tocID":"db2_db_cross_restore_standalone_cdm_v9.x-d39536e34843","next":"db2_db_cross_restore_standalone_cdm_v9.x-d39536e34843"},{"title":"Db2 database cross restore for DPF environment","shortdesc":"<p class=\"shortdesc\">The Db2 database cross restore process to different instances in a Database         Partitioning Feature environment involves creating and editing a template script. The         modified script then migrates data while maintaining data integrity in CDM versions         9.x.<\/p>","href":"db2\/db2_db_cross_restore_dpf_cdm_v9.x.html","attributes":{"data-id":"db2_db_cross_restore_dpf_cdm_v9.x"},"menu":{"hasChildren":false},"tocID":"db2_db_cross_restore_dpf_cdm_v9.x-d39536e34887","next":"db2_db_cross_restore_dpf_cdm_v9.x-d39536e34887"},{"title":"Restoring Db2 databases for HADR environment","shortdesc":"<p class=\"shortdesc\">In CDM version 9.x, when the source and target instances are the same, restore a         database with the same instance for High Availability Disaster Recovery         environment.<\/p>","href":"db2\/restoring_db2_db_hadr_cdm_v9.x.html","attributes":{"data-id":"restoring_db2_db_hadr_cdm_v9.x"},"menu":{"hasChildren":false},"tocID":"restoring_db2_db_hadr_cdm_v9.x-d39536e34931","topics":[]}]}};